var COLS=D.cols,ROWS=D.rows,CW=6,CH=12,N=COLS*ROWS;
var GCX=600,GCY=600,GR=506,GROUND=[93,97],BG0='#02030a';
function halfW(row){var y=row*CH+CH/2,d=GR*GR-(y-GCY)*(y-GCY);return d>0?Math.sqrt(d)/CW:0;}
