 cv.setAttribute('role','img');cv.setAttribute('aria-label','Bola de nieve con el Obelisco, un muñeco de nieve en una reposera y pinos navideños. Tocá para agitar.');
 wrap.appendChild(cv);el.appendChild(wrap);
 var ctx=cv.getContext('2d');ctx.scale(DPR,DPR);
 ctx.font='10.5px ui-monospace,"DejaVu Sans Mono",Menlo,Consolas,monospace';
 ctx.textAlign='center';ctx.textBaseline='middle';
 var ch=new Array(N),cur=new Array(N),r,c,i;
 for(r=0;r<ROWS;r++)for(c=0;c<COLS;c++){i=r*COLS+c;ch[i]=D.chars[r][c];cur[i]=D.pal[D.idx[i]];}
 function clearCell(x,y){if(transparent)ctx.clearRect(x,y,CW,CH);else{ctx.fillStyle=bg;ctx.fillRect(x,y,CW,CH);}}
 function drawCell(i){var r=(i/COLS)|0,c=i%COLS,x=c*CW,y=r*CH;clearCell(x,y);
  if(ch[i]!==' '){ctx.fillStyle=cur[i];ctx.fillText(ch[i],x+CW/2,y+CH/2+0.5);}}
 if(!transparent){ctx.fillStyle=bg;ctx.fillRect(0,0,COLS*CW,ROWS*CH);}
 for(i=0;i<N;i++)if(ch[i]!==' ')drawCell(i);
 var still=!!opts.still||window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;
 if(still)return{shake:function(){},destroy:function(){wrap.remove();}};

 var L=D.lights.map(function(l){return{i:l[0]*COLS+l[1],ci:l[2],ph:Math.random()*6.28,sp:1.5+Math.random()*2.5};});
