function auto(){var els=document.querySelectorAll('[data-snowglobe]');for(var i=0;i<els.length;i++){var e=els[i];if(e.__sg)continue;e.__sg=mount(e,{bg:e.getAttribute('data-bg')||undefined,still:e.hasAttribute('data-still')});}}
